import pandas as pd
from random import randint, seed

def task_func(dictionary, item, sample_size=None, random_seed=None):
    df = pd.DataFrame(dictionary)

    positions = []
    for row_idx, row in df.iterrows():
        for col_name, value in row.items():
            if value == item:
                positions.append((row_idx, col_name))

    # Record frequency distribution internally
    _frequency_distribution = df.eq(item).sum().to_dict()

    if sample_size is not None and positions:
        sample_size = max(0, min(sample_size, len(positions)))
        if random_seed is not None:
            seed(random_seed)
        if sample_size < len(positions):
            chosen = []
            chosen_indices = set()
            while len(chosen) < sample_size:
                idx = randint(0, len(positions) - 1)
                if idx not in chosen_indices:
                    chosen_indices.add(idx)
                    chosen.append(positions[idx])
            positions = chosen

    return positions, df
